<template>
  <div class="dashboard">
   <div class="container-fluid">
    <div class="row">

      <div class="col-2 mt-2" v-for="(colegio, i) in colegios" :key="i">
        <div class="hold-colegio">
          <div class="title-colegio pt-2">{{ colegio.unidade }}</div>
          <div class="porcent-colegio">{{ colegio.porcent }}%</div>
          <div class="clearfix"></div>
          <div class="progress-bar mt-3">
          <div 
            class="num-progress" 
            :class="getBarClass(colegio.porcent)"
            :style="{ width: colegio.porcent + '%' }"
          ></div>

          </div>
          <div class="legenda-colegio pt-2">dos processos concluídos</div>

        </div>
      </div>

      

    </div>
   </div>
  </div>
</template>
<script>
import { realtimeDb } from '../services/firebase'
//import { ref, get } from 'firebase/database'  

export default {
  name: 'DashboardView',

  data() {
    return {
      email: "",
      server: "http://localhost:8080",
      colegios: []
    }
  },

  mounted() {
    this.getProposito()
  },

  methods: {
    async getProposito() {
      try {
        console.log("📡 Conectando ao Firebase em tempo real...")

        const { ref, onValue, off } = await import('firebase/database')
        const projetosRef = ref(realtimeDb, 'projetos')

        // Antes de criar um novo listener, remove qualquer anterior (boa prática)
        off(projetosRef)

        // Escuta mudanças em tempo real
        onValue(projetosRef, (snapshot) => {
          const data = snapshot.val()

          if (data) {
            console.log("📦 Atualização recebida:", data)
            this.colegios = Object.values(data)
          } else {
            console.warn("⚠️ Nenhum dado encontrado em /projetos")
            this.colegios = []
          }
        })
      } catch (error) {
        console.error("❌ ERRO ao acessar Firebase:", error)
      }
    },

    getBarClass(porcent) {
      const valor = parseFloat(porcent) || 0

      if (valor <= 49) return 'bad-bar'
      if (valor <= 75) return 'normal-bar'
      return 'success-bar'
    },
  }
}
</script>
